mapper.sql:
where 1=1

		and corg_llave = #{llaveTabla}


		and corg_estado = #{estado}


		and corg_nombre = #{nombre}


		and corg_principal = #{principal}


		and corg_servidor = #{servidor}


		and corg_usuariosystem = #{usuarioSystem}


		and borg_sincronizacion = #{sincronizacionFilter}


		and corg_codigo = #{codigo}


		and corg_servidorcorreo = #{servidorCorreo}


		and (corg_nombre like ('%' || #{filtroParametro} || '%') or corg_codigo like ('%' || #{filtroParametro} || '%'))
